/**
 * DIAMOND-FIX: Deep PII Masking + Forensic Normalization
 */
const e = $json;
const mask = (str) => {
  if (!str) return '';
  return str.toString()
    .replace(/\+?[1-9]\d{1,14}/g, '[PHONE_REDACTED]') // E.164
    .replace(/\b[\w\.-]+@[\w\.-]+\.\w{2,4}\b/gi, '[EMAIL_REDACTED]') // Email
    .replace(/(adresse|villa|lot|rue|n°)\s+([^,.\n]{5,50})/gi, '$1 [ADDRESS_REDACTED]') // Algerian Address patterns
    .replace(/\b(dz|alg|id|key)\d{8,30}\b/gi, '[SENSITIVE_REDACTED]'); // IDs/Keys
};

const burstCount = $("B0 - Track Error Burst").item.json || 0;

return [{
  json: {
    workflow: e.workflow?.name || e.workflow || 'unknown',
    node: e.node?.name || e.node || 'unknown',
    message: mask(e.error?.message || e.message || 'No error message'),
    stack: mask(e.error?.stack || e.stack || ''),
    time: new Date().toISOString(),
    executionId: e.execution?.id || e.executionId || '',
    isBurst: burstCount > 10
  }
}];

