/**
 * DIAMOND-FIX: Burst-aware Alerting
 */
const url = ($env.ALERT_WEBHOOK_URL || '').toString();
if (!url || $json.isBurst) {
  return [{json:{ok:true, alerted:false, reason: $json.isBurst ? 'BURST_THROTTLED' : 'NO_WEBHOOK_URL'}}];
}

try {
  await $httpRequest({method:'POST',url,body:$json,json:true,timeout:15000});
  return [{json:{ok:true, alerted:true}}];
} catch(err) {
  return [{json:{ok:false, error: err.message}}];
}
